steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: <TOKEN>" \
  -d '{
    "query": "{
      users(query: \"Maya Chen\") {
        nodes {
          id
          name
          email
        }
      }
      projects(limit: 50) {
        nodes {
          id
          name
        }
      }
      teams(limit: 50) {
        nodes {
          id
          name
          milestones(limit: 50) {
            nodes {
              id
              name
              type
            }
          }
        }
      }
    }"
  }'
